@icontract.snapshot(lambda xyz: np.copy(xyz), name="xyz_before")
@icontract.ensure(lambda xyz, xyz_before: np.array_equal(xyz, xyz_before), "Input xyz is not modified.")
@icontract.ensure(lambda result: isinstance(result, tuple) and len(result) == 3, "Function must return a tuple of three arrays: (radius, inclination, azimuth).")
@icontract.ensure(lambda result, xyz: all(isinstance(a, np.ndarray) and a.ndim == 1 and a.shape[0] == xyz.shape[0] for a in result), "Each output is a 1-D ndarray with length equal to the number of input points.")
@icontract.ensure(lambda result: np.all(result[0] >= 0.0), "Radius is non-negative.")
@icontract.ensure(lambda result: all(np.all(np.isfinite(a)) for a in result), "All outputs must be finite numbers.")
@icontract.ensure(lambda result, xyz: np.allclose(result[0], np.linalg.norm(xyz, axis=1), rtol=1e-9, atol=1e-12), "Radius equals the Euclidean norm of the Cartesian coordinates.")
@icontract.ensure(lambda result, degrees: np.all((0.0 - 1e-12 <= result[1]) & (result[1] <= ((180.0 if degrees else np.pi) + 1e-12))), "Polar angle (inclination) is in [0, 180] degrees or [0, pi] radians.")
@icontract.ensure(lambda result, degrees: np.all((-(180.0 if degrees else np.pi) - 1e-12 <= result[2]) & (result[2] <= ((180.0 if degrees else np.pi) + 1e-12))), "Azimuthal angle is in [-180, 180] degrees or [-pi, pi] radians.")
@icontract.ensure(
    lambda result, xyz, degrees: np.allclose(
        np.column_stack((
            result[0] * np.sin((np.deg2rad(result[1]) if degrees else result[1])) * np.cos((np.deg2rad(result[2]) if degrees else result[2])),
            result[0] * np.sin((np.deg2rad(result[1]) if degrees else result[1])) * np.sin((np.deg2rad(result[2]) if degrees else result[2])),
            result[0] * np.cos((np.deg2rad(result[1]) if degrees else result[1]))
        )),
        xyz,
        rtol=1e-9,
        atol=1e-12
    ),
    "Converting the result back to Cartesian reproduces the input within tolerance."
)

@icontract.snapshot(lambda xyz: xyz.shape, name="xyz_shape")
@icontract.snapshot(lambda xyz: np.array(xyz, copy=True), name="xyz_before")
@icontract.ensure(lambda radius: isinstance(radius, np.ndarray))
