@icontract.ensure(lambda xyz_shape, inclination: inclination.ndim == 1 and inclination.shape == (xyz_shape[0],))
@icontract.ensure(lambda xyz_shape, azimuth: azimuth.ndim == 1 and azimuth.shape == (xyz_shape[0],))
@icontract.ensure(lambda radius: np.all(radius >= 0))
@icontract.ensure(
    lambda radius, inclination, azimuth, degrees, xyz_before:
    np.allclose(
        np.stack(
            [
                radius * np.sin(np.deg2rad(inclination) if degrees else inclination)
                * np.cos(np.deg2rad(azimuth) if degrees else azimuth),
                radius * np.sin(np.deg2rad(inclination) if degrees else inclination)
                * np.sin(np.deg2rad(azimuth) if degrees else azimuth),
                radius * np.cos(np.deg2rad(inclination) if degrees else inclination),
            ],
            axis=1,
        ),
        xyz_before,
        rtol=1e-12,
        atol=1e-12,
    )
)
@icontract.ensure(
    lambda radius, xyz_before:
    np.allclose(
        radius,
        np.sqrt(np.sum(xyz_before ** 2, axis=1)),
        rtol=1e-12,
        atol=1e-12,
    )
